package com.example.inventory.controller; import com.example.inventory.model.StockItem; import com.example.inventory.service.InventoryService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/inventory") public class InventoryController { private final InventoryService s; public InventoryController(InventoryService s){this.s=s;} @GetMapping("/{sku}") public StockItem get(@PathVariable String sku){return s.get(sku);} @PostMapping("/{sku}/reserve") public StockItem reserve(@PathVariable String sku,@RequestParam int quantity){return s.reserve(sku,quantity);} }
